                    "--api_key":"benchmark-placeholder-api-key"
                }
            },
            "Next": "Processa Dados"
         },

        "Processa Dados": {
            "Type":"Task",
            "Resource":"arn:aws:states:::glue:startJobRun.sync",
            "Parameters": {
                "JobName":"glue-job-transforma-dados",
                "Arguments": {
                    "--bucketDataLakeStaging":"benchmark-datalake-staging-000000000000",
                    "--bucketDataLakeBronze":"benchmark-datalake-bronze-000000000000",
                    "--bucketDataLakeSilver":"benchmark-datalake-silver-000000000000",
                    "--pastaArqs":"clima",
                    "--key":"benchmark-placeholder-key"
               }
            },
            "End":true
        }
    }
}

properties.definition:
{
    "Comment":"A description of the sample glue job state machine using Terraform",
    "StartAt":"Glue StartJobRun",
    "States": {

        "Glue StartJobRun": {
            "Type":"Task",
            "Resource":"arn:aws:states:::glue:startJobRun.sync",
            "Parameters": {
                "JobName":"${aws_glue_job.etl_jobs.name}",
                "Arguments": {
                    "--cidade":"${var.Cidade_API_Clima}",
                    "--bucketDataLakeStaging":"${var.bucket_staging_lake}-${local.account_id}",
                    "--pastaArqs":"clima",
                    "--api_key":"${var.key_api}"
                }
            },
            "Next": "Processa Dados"
         },

        "Processa Dados": {
            "Type":"Task",
            "Resource":"arn:aws:states:::glue:startJobRun.sync",
            "Parameters": {
                "JobName":"${aws_glue_job.transforma_job.name}",
                "Arguments": {
                    "--bucketDataLakeStaging":"${var.bucket_staging_lake}-${local.account_id}",
                    "--bucketDataLakeBronze":"${var.bucket_bronze_lake}-${local.account_id}",
                    "--bucketDataLakeSilver":"${var.bucket_silver_lake}-${local.account_id}",
                    "--pastaArqs":"clima",
                    "--key":"${var.keyTraduz}"
               }
            },
            "End":true
        }
    }
}
